import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

import { parseMappa2SecondaryWater } from '@/ui/idleVillage/config/mappa2SecondaryWaterConfig';

/**
 * R-299 (2026-10-30): the painted surf around the west-rim sea arch and stacks animates as a
 * `seaPatches` entry in `secondary-water.json` — the same flow-pose recipe as bay_2/delta_sea
 * (PLAN-095), generated by `scripts/build-mappa2-sea-arch-patch.py` and mirrored in
 * `build-mappa2-assets.py`. If the JSON entry or its pose files drift, the runtime silently
 * renders a static sea again, so the real shipped contract is checked here.
 */
const BASE = resolve(__dirname, '../../../public/assets/world/mappa2/base');

const secondaryWater = parseMappa2SecondaryWater(
  JSON.parse(readFileSync(resolve(BASE, 'secondary-water.json'), 'utf-8')),
);

describe('mappa2 sea_arch patch (R-299)', () => {
  const patch = secondaryWater.seaPatches?.find((p) => p.id === 'sea_arch');

  it('is registered in secondary-water.json over the west-rim arch', () => {
    expect(patch).toBeDefined();
    const r = patch!.flowPoses.rect;
    // The arch coast sits on the west rim (x ~0-560, y ~350-800): the rect must contain it.
    expect(r.x).toBeLessThanOrEqual(30);
    expect(r.x + r.width).toBeGreaterThanOrEqual(500);
    expect(r.y).toBeLessThanOrEqual(380);
    expect(r.y + r.height).toBeGreaterThanOrEqual(750);
  });

  it('ships every declared pose frame on disk (all seaPatches)', () => {
    for (const p of secondaryWater.seaPatches ?? []) {
      for (const frame of p.flowPoses.frames) {
        expect(existsSync(resolve(BASE, frame)), `${p.id}: missing ${frame}`).toBe(true);
      }
    }
  });

  it('has animated poses (consecutive frames differ, like the other patches)', () => {
    const frames = patch!.flowPoses.frames;
    const f0 = readFileSync(resolve(BASE, frames[0]));
    const f1 = readFileSync(resolve(BASE, frames[1]));
    expect(f0.equals(f1), 'sea_arch_f0 and sea_arch_f1 are byte-identical — the patch is static').toBe(false);
  });
});
